const fs = require('fs');
const raw = $input.first().json.choices[0].message.content;
const data = JSON.parse(raw);
const prev = $('Extract Params').item.json;
let body = (data.body || '').split('\n').filter(line => !/^\s*#+\s*[\u4e00-\u9fa5]/.test(line)).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const tagsClean = [...new Set((data.tags || []).map(t => t.replace(/^#+/, '').trim()).filter(Boolean))];
const ts = new Date().toISOString().slice(0,19).replace(/[-:T]/g,'');
const draftDir = `/home/david/xhs-drafts/${ts}`;
fs.mkdirSync(draftDir, { recursive: true });
const mdPath = `${draftDir}/note.md`;
const md = `# ${data.title}\n\n${body}\n\n${tagsClean.map(t=>'#'+t).join(' ')}\n`;
fs.writeFileSync(mdPath, md);
const prompts = data.image_prompts || [];
const n = Math.min(prev.num_images, prompts.length);
const result = [];
for (let i = 0; i < n; i++) {
  result.push({ json: { prompt: prompts[i], index: i + 1, total: n, draft_dir: draftDir, md_path: mdPath, title: data.title, body: body, tags: tagsClean, tg_chat_id: prev.tg_chat_id, tg_bot_token: prev.tg_bot_token }});
}
return result;

const item = $input.first().json;
const seed = Math.floor(Math.random() * 1000000000);
const workflow = {
  '1': {class_type:'UNETLoader', inputs:{unet_name:'qwen_image_fp8_e4m3fn.safetensors', weight_dtype:'default'}},
  '2': {class_type:'CLIPLoader', inputs:{clip_name:'qwen_2.5_vl_7b_fp8_scaled.safetensors', type:'qwen_image'}},
