return [{ json: { comfy_body: { prompt: workflow, client_id: 'n8n' }, ...item }}];

const fs = require('fs');
const http = require('http');
const promptId = $input.first().json.prompt_id;
const prev = $('Build Comfy Workflow').item.json;
async function getJson(url) { return new Promise((res, rej) => http.get(url, r => { let d=''; r.on('data',c=>d+=c); r.on('end',()=>{try{res(JSON.parse(d))}catch(e){rej(e)}}); }).on('error', rej)); }
async function getBinary(url) { return new Promise((res, rej) => http.get(url, r => { const c=[]; r.on('data',b=>c.push(b)); r.on('end',()=>res(Buffer.concat(c))); }).on('error', rej)); }
const dl = Date.now() + 900000;
let result = null;
while (Date.now() < dl) {
  const d = await getJson(`http://127.0.0.1:8189/history/${promptId}`);
  if (d[promptId]) {
    const e = d[promptId], st = e.status || {};
    if (st.completed) {
      for (const nid in e.outputs || {}) {
        for (const img of (e.outputs[nid].images || [])) {
          const u = `http://127.0.0.1:8189/view?filename=${img.filename}&subfolder=${img.subfolder||''}&type=output`;
          const buf = await getBinary(u);
          const dest = `${prev.draft_dir}/img-${String(prev.index).padStart(2,'0')}-${img.filename}`;
          fs.writeFileSync(dest, buf);
          result = { saved: dest, filepath: dest };
          break;
        }
        if (result) break;
      }
      break;
    }
    if (st.status_str === 'error') { result = { error: 'workflow error' }; break; }
  }
  await new Promise(r => setTimeout(r, 3000));
}
if (!result) result = { error: 'timeout' };
return [{ json: { ...result, ...prev }}];

const fs = require('fs');
const dir = $('Keep First (dedup)').item.json.draft_dir;
const files = fs.readdirSync(dir).filter(f => f.startsWith('img-')).sort();
const prev = $('Extract Params').item.json;
return files.map(f => ({
  json: { filename: f, filepath: `${dir}/${f}`, tg_chat_id: prev.tg_chat_id, tg_bot_token: prev.tg_bot_token },
  binary: { data: { data: fs.readFileSync(`${dir}/${f}`).toString('base64'), mimeType: 'image/png', fileName: f }}
}));
